-- 575: Original BrillaPrep WASSCE English Language sprint 3 beta questions, part 5 of 9 (batch wassce-english-sprint3-001).
-- Original BrillaPrep curriculum-aligned practice content; not official WAEC material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_575_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_575_guard;
INSERT INTO _migration_575_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_s3_002' AND NOT (q.topic_id IS 'topic_wassce_p2_eng_cmp' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Read the passage, then answer. — "When the pipe-borne water failed in Nkwanta, the women rose before dawn to queue at the only borehole. Efua carried two jerrycans on her head and her baby on her back. Then the assemblyman had a second borehole drilled, and the queues grew shorter. "Water is life," Efua said, "but so is the time we lose fetching it."" What did Efua carry on her head?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. her baby","B. two jerrycans","C. a basket of wares","D. a bundle of firewood"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Efua carried "two jerrycans on her head and her baby on her back", so the baby was on her back, not her head; no basket or firewood is mentioned. Therefore the correct answer is B: two jerrycans.' AND q.difficulty IS 'easy' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '60' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_s3_002' AND NOT (r.batch_id IS 'wassce-english-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE English Language practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_575_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_s3_003' AND NOT (q.topic_id IS 'topic_wassce_p2_eng_cmp' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Read the passage, then answer. — "When the pipe-borne water failed in Nkwanta, the women rose before dawn to queue at the only borehole. Efua carried two jerrycans on her head and her baby on her back. Then the assemblyman had a second borehole drilled, and the queues grew shorter. "Water is life," Efua said, "but so is the time we lose fetching it."" Who had the second borehole drilled?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Efua","B. the headmistress","C. the assemblyman","D. the women of the town"]' AND q.correct_answer IS 'C' AND q.explanation IS 'The passage states that "the assemblyman had a second borehole drilled"; Efua, a headmistress and the women themselves are not credited with it. Therefore the correct answer is C: the assemblyman.' AND q.difficulty IS 'easy' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '60' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_s3_003' AND NOT (r.batch_id IS 'wassce-english-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE English Language practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_575_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_s3_004' AND NOT (q.topic_id IS 'topic_wassce_p2_eng_cmp' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Read the passage, then answer. — "When the pipe-borne water failed in Nkwanta, the women rose before dawn to queue at the only borehole. Efua carried two jerrycans on her head and her baby on her back. Then the assemblyman had a second borehole drilled, and the queues grew shorter. "Water is life," Efua said, "but so is the time we lose fetching it."" The queues grew shorter because' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. the pipe-borne water was restored","B. the women stopped fetching water","C. the rains came","D. a second borehole was drilled"]' AND q.correct_answer IS 'D' AND q.explanation IS 'The shorter queues follow the new borehole directly: it was drilled "and the queues grew shorter"; no restoration, boycott or rain is mentioned. Therefore the correct answer is D: a second borehole was drilled.' AND q.difficulty IS 'easy' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '60' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_s3_004' AND NOT (r.batch_id IS 'wassce-english-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE English Language practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_575_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_s3_017' AND NOT (q.topic_id IS 'topic_wassce_p2_eng_ess' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Linking expressions such as "furthermore", "however" and "consequently" are used in an essay to' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. connect ideas and guide the reader from one point to the next","B. make the sentences longer than necessary","C. replace full stops throughout the essay","D. display difficult vocabulary"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Transitions signal addition, contrast or result, so the reader follows the argument smoothly; they are signposts of coherence, not padding, punctuation substitutes or ornament. Therefore the correct answer is A: connect ideas and guide the reader from one point to the next.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '45' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_s3_017' AND NOT (r.batch_id IS 'wassce-english-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE English Language practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_575_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_s3_020' AND NOT (q.topic_id IS 'topic_wassce_p2_eng_ess' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which approach best demonstrates balance in an argumentative essay?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. The writer lists ten points without explaining any of them.","B. The writer ridicules the character of the opposing side.","C. The writer copies the question as the conclusion.","D. The writer presents three points for the motion, concedes one opposing point and answers it."]' AND q.correct_answer IS 'D' AND q.explanation IS 'Balance means engaging the other side: concede the strongest opposing point and rebut it while developing your own case; listing, ridicule and copying the question are faults. Therefore the correct answer is D: The writer presents three points for the motion, concedes one opposing point and answers it..' AND q.difficulty IS 'hard' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '45' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Evaluate' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_s3_020' AND NOT (r.batch_id IS 'wassce-english-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE English Language practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_eng_s3_002', 'topic_wassce_p2_eng_cmp', 'subj_wassce_english', 'exam_wassce', NULL, NULL, 'Read the passage, then answer. — "When the pipe-borne water failed in Nkwanta, the women rose before dawn to queue at the only borehole. Efua carried two jerrycans on her head and her baby on her back. Then the assemblyman had a second borehole drilled, and the queues grew shorter. "Water is life," Efua said, "but so is the time we lose fetching it."" What did Efua carry on her head?', 'multiple_choice', NULL, '["A. her baby","B. two jerrycans","C. a basket of wares","D. a bundle of firewood"]', 'B', 'Efua carried "two jerrycans on her head and her baby on her back", so the baby was on her back, not her head; no basket or firewood is mentioned. Therefore the correct answer is B: two jerrycans.', 'easy', '3', '1', '60', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, NULL);
